  "core_transformation_summary": "Transforms the forward problem of finding minimal initial energy into an inverse design task: given initial energy and a target final energy, determine the minimal total modification to building heights that makes the bot succeed.",
  "difference_plan": {
    "changed_axes": ["C", "O", "V"],
    "rationale": "Core constraints now include modification operations and a target equality; objective shifts from minimizing initial energy to minimizing modification cost; invariants change from monotonicity to linear sensitivity and optimality conditions.",
    "summary": "Shift from a forward monotonic search to a constrained minimization over discrete modifications."
  },
  "new_schema": {
    "problem_id": "inverse_design_urban_commute_001",
    "source": "derived_from_hackerrank",
    "input_structure": {
      "type": "multiple",
      "components": [
        {
          "name": "n",
          "type": "integer",
          "range": { "min": 1, "max": 100000 }
        },
        {
          "name": "E0",
          "type": "integer",
          "range": { "min": 0, "max": 1000000000 }
        },
        {
          "name": "F",
          "type": "integer",
          "range": { "min": 0, "max": 1000000000 }
        },
        {
          "name": "levels",
          "type": "array",
          "length": "n",
          "element_type": "integer",
          "value_range": { "min": 1, "max": 100000 }
        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "energy_update",
          "description": "Starting with e = E0, for each level l_i in the modified array (l_i = original_level_i + d_i), update e = 2*e - l_i.",
          "formal": "For i=1..n, e_{i} = 2*e_{i-1} - (l_i + d_i), with e_0 = E0."
        },
        {
          "name": "energy_non_negative",
          "description": "Energy must never drop below zero during the process.",
          "formal": "For all i=0..n, e_i >= 0."
        },
        {
          "name": "target_final_energy",
          "description": "The final energy must exactly equal the target F.",
          "formal": "e_n = F."
        },
        {
          "name": "modification_rule",
          "description": "For each level i, you may choose an integer adjustment d_i (positive or negative). The cost is the sum of absolute adjustments.",
          "formal": "d_i ∈ Z, cost = Σ |d_i|."
        }
      ]
    },
    "objective": {
      "type": "minimize_value",
      "description": "minimize the total modification cost Σ |d_i| such that the energy constraints are satisfied.",
      "target": "modification_cost",
      "requires_solution": false
    },
    "invariant": {
      "invariants": [
        {
          "name": "linear_energy_dependence",
          "description": "The final energy e_n can be expressed as 2^n * E0 - Σ (2^{n-i} * (l_i + d_i)), a linear function of the adjustments d_i.",
          "properties": {},
          "evidence_source": "derived"
        },
        {
          "name": "convex_cost",
          "description": "The total cost function is convex and separable, leading to an optimisation problem that can be solved by ordering or linear programming.",
          "properties": {},
          "evidence_source": "mathematical"
        },
        {
          "name": "minimality_lower_bound",
          "description": "Any feasible solution must satisfy Σ d_i * 2^{n-i} = K (a constant derived from E0, F, and original levels), and the minimum L1-norm solution corresponds to a specific selection of modifications.",
          "properties": {},
          "evidence_source": "proof_required"
        }
      ]
    },
    "difficulty": "medium"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "binary search on monotonic function",
    "reusable_subroutines": "energy computation function (e = 2e - h)",
    "new_solver_core": "minimization of L1-norm subject to linear constraints, solved by transforming to a linear programming problem or using convex optimization (e.g., median property for absolute deviations)",
    "new_proof_obligation": "Proving that the optimal solution must satisfy a certain ordering property to minimize total absolute change, and that the energy constraints lead to a feasible region that can be searched efficiently.",
    "why_direct_reuse_fails": "The original problem only requires monotonic search, while the inverse design requires solving an optimization over modifications with cost function and additional equality constraints, fundamentally changing the solution approach."
  },
  "anti_shallow_rationale": "The transformation shifts the computational task from finding a minimal input value to designing a minimal set of modifications under a strict target outcome. While the underlying energy transition function is preserved, the core decision problem becomes an inverse design optimization with new constraints and a different objective, requiring a novel algorithm rather than a simple adaptation of the original binary search.",
  "applied_helpers": [
    {
      "id": "target_result_binding",
      "selection_reason": "needed to define the inverse goal: specify a target final energy that must be achieved",
      "affected_axes": ["C", "O"],
      "schema_changes": [
        "objective: switched from minimizing initial energy to minimizing modification cost",
        "core_constraints: added requirement that final energy equals target F"
      ],
      "innovation_reason": "flips the direction of the problem from forward computation to goal-driven design",
      "difficulty_reason": "introduces a target constraint that couples all modification decisions"
    },
    {
      "id": "edit_operation_contract",
      "selection_reason": "defines the allowed modifications to building heights, making the design space concrete",
      "affected_axes": ["C", "V"],
      "schema_changes": [
        "core_constraints: added rule that each modification changes a level by ±1 with cost 1",
        "invariant: must relate modifications to energy outcome"
      ],
      "innovation_reason": "formalizes the inverse design as an optimization over a well-defined discrete operation space",
      "difficulty_reason": "requires reasoning about the effect of each modification on energy, and proving feasibility bounds"
    },
    {
      "id": "minimality_or_certificate_lock",
      "selection_reason": "required to demand the minimal modification cost, not just any feasible design",
      "affected_axes": ["O", "V"],
      "schema_changes": [
        "objective: explicitly requires minimization of total cost",
        "invariant: must support a lower bound argument to prove optimality"
      ],
      "innovation_reason": "guarantees the answer is non-trivial and requires a proof of optimality",
      "difficulty_reason": "adds the complexity of proving that a solution is indeed minimal, often necessitating combinatorial optimization techniques"
    }
  ],
  "shared_core_summary": "",
  "shared_core_anchors": {
    "shared_state": "",
    "shared_transition": "",
    "shared_decision_basis": ""
  },
  "seed_a_indispensable_obligation": "",
  "seed_b_indispensable_obligation": "",
