        "target": "beauty",
        "requires_solution": false
      },
      "invariant": {
        "invariants": [
          {
            "name": "transformed_lcp_correspondence",
            "description": "将每个单词与其反转字符串交错合并形成新字符串后,任意两个单词的原始美丽度 min(lp,ls)^2 恰好等于新字符串间最长公共前缀长度一半的平方,从而将原问题转化为在新字符串集合上的最长公共前缀配对优化。",
            "properties": {
              "formula": "for any words w1,w2, let t1=interleave(w1,reverse(w1)), t2=interleave(w2,reverse(w2)). Then min(lcp(w1,w2), lcs(w1,w2)) = lcp(t1,t2) // 2"
            },
            "evidence_source": "both"
          },
          {
            "name": "adjacent_min_lcp_upper_bound",
            "description": "将转换后的字符串按字典序排序后,序列中任意一个跨过全局最小相邻LCP索引的字符串对的LCP都不会超过该最小相邻LCP值。这一性质允许以最小相邻LCP为分割点进行分治,保证跨部分配对的贡献被约束。",
            "properties": {
              "condition": "对于已排序的序列 t,若 p 使得 lcp(t_p, t_{p+1}) 为所有相邻对中的最小值,则对所有 i ≤ p < j,lcp(t_i,t_j) ≤ lcp(t_p,t_{p+1})。"
