          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
