请以给定角色完成单条规则资格审查。
要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名全局耦合审查官，重点判断局部独立单元是否能被共享资源或全局守恒自然绑定。",
  "rule_under_review": {
    "id": "independent_components_to_global_coupling",
    "family": "global_coupling",
    "audit_tags": [
      "single_seed",
      "global_constraint",
      "coupled_components"
    ],
    "handler": "independent_components_to_global_coupling",
    "enabled": true,
    "summary": "把原本可独立处理的分量、位置或查询扩展为共享资源和全局守恒耦合题。",
    "eligibility": {
      "required_seed_properties": [
        "原题存在可分解的局部单元",
        "局部单元之间能通过共享资源、总量或全局选择自然耦合"
      ],
      "forbidden_seed_properties": [
        "各单元完全没有共同变量",
        "全局约束只能靠无关背景硬加"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "independent_components_to_global_coupling",
      "target_shift": "从局部独立求解改成全局耦合求解",
      "new_obligation": "在共享预算、守恒量或跨组件依赖下统一求解"
    },
    "helpers": [
      {
        "id": "shared_resource_constraint",
        "summary": "把多个局部单元绑定到同一个共享资源或守恒量。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让原来的分而治之不再成立。",
        "difficulty_role": "要求算法在全局预算下统一选择局部决策。",
        "prompt_guidance": [
          "共享资源必须直接约束多个局部单元。",
          "目标必须依赖全局分配结果。"
        ],
        "redlines": [
          "不能只给每个单元独立加同一限制。",
          "不能把全局约束写成无影响上限。"
