          "V"
        ],
        "innovation_role": "把局部答案集合提升成整体决策对象。",
        "difficulty_role": "要求证明局部取舍组合后的整体最优性。",
        "prompt_guidance": [
          "目标要强调整体最优或整体可行。",
          "不变量要阻止局部贪心直接拼接。"
        ],
        "redlines": [
          "不能只把局部答案加总。",
          "不能没有全局一致性证明。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "必须有共享资源或跨组件依赖",
        "局部单元不能继续独立求解",
        "必须定义全局最优或全局可行责任"
