请以给定角色完成单条规则资格审查。
要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名博弈化审查官，重点判断原题操作是否能自然转化为双方轮流选择。",
  "rule_under_review": {
    "id": "deterministic_process_to_game_outcome",
    "family": "game_transformation",
    "audit_tags": [
      "single_seed",
      "game",
      "adversarial_choice"
    ],
    "handler": "deterministic_process_to_game_outcome",
    "enabled": true,
    "summary": "把单人确定性选择或操作过程扩展为双方最优行动下的胜负或得分差题。",
    "eligibility": {
      "required_seed_properties": [
        "原题存在可轮流选择、拿取、移动或改变状态的自然操作",
        "不同操作会改变后续可选状态"
      ],
      "forbidden_seed_properties": [
        "操作顺序固定且没有选择自由度",
        "对抗方只能靠故事背景硬造"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "deterministic_process_to_game_outcome",
      "target_shift": "从单人过程改成双方最优博弈",
      "new_obligation": "定义行动规则、胜负目标和博弈状态不变量"
    },
    "helpers": [
