          ]
        },
        {
          "name": "allow_unused_elements",
          "description": "不要求使用所有物品标签；任意子集均可组成合法方案。",
          "formal": "使用的物品总数 ≤ N。",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "alphabet_restriction",
          "description": "所有物品标签仅由小写英文字母组成。",
          "formal": "每个物品标签 ∈ [a-z]+。",
          "source_sections": [
            "constraints"
          ]
        },
        {
          "name": "beauty_definition",
          "description": "对于一对物品标签，其匹配度定义为 min(lcp, lcs)^2，其中 lcp 为最长公共前缀长度，lcs 为最长公共后缀长度。整个方案的匹配度为所有配对匹配度之和。",
          "formal": "beauty((x,y)) = min(lcp(x,y), lcs(x,y))^2，方案总匹配度 = Σ beauty(pair)。",
