          ]
        }
      ]
    },
    "objective": {
      "type": "count_optimal_solutions",
      "description": "计算所有总匹配度最大的不同收纳方案的数量，输出该数量模 1_000_000_007。",
      "target": "number_of_max_beauty_solutions",
