messages.content:
请以给定角色完成单条规则资格审查。
要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名计数化审查官，重点判断解空间、去重规则和有限性是否足够清晰。",
  "rule_under_review": {
    "id": "existence_to_counting",
    "family": "objective_upgrade",
    "audit_tags": [
      "single_seed",
      "counting",
      "deduplication"
    ],
    "handler": "existence_to_counting",
    "enabled": true,
    "summary": "把存在性或单一最优值问题改成一个对象明确、去重规则明确的计数题。",
    "eligibility": {
      "required_seed_properties": [
        "解空间有限",
        "不同解之间的等价关系能说清楚",
        "可以按某种单元拆分并汇总"
      ],
      "forbidden_seed_properties": [
        "解空间天然无限",
        "去重规则说不清楚"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "O",
        "C",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "existence_to_counting",
      "target_shift": "从存在性或最优值改成计数",
      "new_obligation": "定义清楚计数对象、有限性和去重规则"
    },
    "helpers": [
      {
        "id": "counting_unit_definition",
        "summary": "明确计数对象、等价关系与不同答案口径。",
        "must_realize_in": [
          "core_constraints",
          "objective",
          "invariant"
        ],
        "target_axes": [
          "C",
          "O",
          "V"
        ],
        "innovation_role": "把原题答案换成对象明确的计数结果。",
        "difficulty_role": "要求解法处理等价类和有限性证明。",
        "prompt_guidance": [
          "把计数对象直接写进目标定义。",
          "把去重口径写进约束或不变量。"
        ],
        "redlines": [
          "不能只补一个模数。",
          "不能不定义什么算不同答案。"
        ]
      },
      {
        "id": "state_factorization",
        "summary": "把解空间拆成可汇总的计数单元。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "让计数从主状态组织方式中自然长出来。",
        "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
        "prompt_guidance": [
          "让核心约束说明如何拆成计数单元。",
          "让不变量解释单元之间如何避免重复。"
        ],
        "redlines": [
          "不能保持原状态结构不动。",
          "不能把计数只当成结果后处理。"
        ]
      },
      {
        "id": "counting_obligation_lock",
        "summary": "把计数责任锁进主求解目标而不是附带统计。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "把原题主目标替换成新的计数义务。",
        "difficulty_role": "要求算法同时承担计数正确性和去重正确性。",
        "prompt_guidance": [
          "让目标定义主导状态转移。",
          "不要保留原判定主目标再顺手计数。"
        ],
        "redlines": [
          "不能继续由原题判定过程主导。",
          "不能把计数目标放进备注。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "必须说明什么样的解算不同",
        "必须说明为什么可数，或者说明取模方式",
        "必须说明按什么单元拆分和汇总"
      ]
    },
    "examples": {
      "positive": "统计所有满足约束的最优构造数，并定义去重与取模。",
      "negative": "把是否存在改成计数，但状态结构和计数对象都没重新定义。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题没有稳定的有限解空间，或者去重规则说不清楚，不适合改成计数题。",
      "difference_insufficient": "改成计数之后没有带来明显的新责任，看起来只是换了答案形式。"
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    }
  },
  "schema_context": {
