          },
          {
            "name": "stanza_pair_structure",
            "description": "A stanza must consist of exactly two words; a verse is a (possibly empty) list of such stanzas.",
            "formal": "A verse is a sequence of pairs {(a_1, b_1), ..., (a_m, b_m)} where each a_i, b_i are chosen from the input words.",
            "source_sections": [
