请以给定角色完成单条规则资格审查。
要求：
- 只能判断该规则是否适合进入下一阶段规划。
- `selection_reason` 直接写结论依据，不要泛泛而谈。
- `evidence` 必须引用 schema、原题摘要或规则声明中的具体证据。
- `score` 取 0 到 1，表示进入后续规划的把握度；拒绝时可以是 0 到 0.49。
- `risk_tags` 只保留高价值风险标签，例如 `low_novelty`、`shared_core_risk`、`semantic_mismatch`。
- 如果 schema 信息不足以判断，返回 `schema_insufficient`。
- 如果不确定，返回 `ineligible`。

{
  "review_type": "eligibility",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名阈值优化审查官，重点判断可行性是否能自然升级为临界参数或极值阈值。",
  "rule_under_review": {
    "id": "feasibility_to_extremal_threshold",
    "family": "threshold_optimization",
    "audit_tags": [
      "single_seed",
      "threshold",
      "extremal_value"
    ],
    "handler": "feasibility_to_extremal_threshold",
    "enabled": true,
    "summary": "把判定或可行性问题扩展为求最小阈值、最大容量或临界参数的优化题。",
    "eligibility": {
      "required_seed_properties": [
        "原题可行性随某个参数具有清晰的单调性或分层结构",
        "阈值变化会改变主约束的可行区域"
      ],
      "forbidden_seed_properties": [
        "没有自然参数可优化",
        "阈值只是在原判定外层做机械二分"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "feasibility_to_extremal_threshold",
      "target_shift": "从判断是否可行改成求临界阈值",
      "new_obligation": "定义阈值、可行区域和临界性证明"
    },
    "helpers": [
      {
        "id": "threshold_parameterization",
        "summary": "把原可行性条件参数化成可搜索的临界阈值。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让目标从真假判断变成极值求解。",
        "difficulty_role": "要求算法处理阈值与可行性的耦合关系。",
        "prompt_guidance": [
          "阈值必须进入核心约束的定义。",
          "目标必须要求输出最小或最大临界参数。"
        ],
        "redlines": [
          "不能只是把 Yes/No 改成 0/1。",
          "不能让阈值脱离主约束。"
        ]
