      "invariant": {
        "invariants": [
          {
            "name": "transformed_lcp_correspondence",
            "description": "将每个单词与其反转字符串交错合并形成新字符串后,任意两个单词的原始美丽度 min(lp,ls)^2 恰好等于新字符串间最长公共前缀长度一半的平方,从而将原问题转化为在新字符串集合上的最长公共前缀配对优化。",
            "properties": {
              "formula": "for any words w1,w2, let t1=interleave(w1,reverse(w1)), t2=interleave(w2,reverse(w2)). Then min(lcp(w1,w2), lcs(w1,w2)) = lcp(t1,t2) // 2"
