    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "forward_solution_to_inverse_design",
      "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
      "new_obligation": "定义目标结果、允许修改和最小性证明"
    },
    "helpers": [
      {
        "id": "target_result_binding",
        "summary": "把原题结果绑定成新题要达成的反向目标。",
        "must_realize_in": [
