        "summary": "把原操作空间拆成双方轮流行动的正式规则。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让原决策过程获得对抗语义。",
        "difficulty_role": "要求算法分析双方最优响应。",
        "prompt_guidance": [
          "行动必须来自原题已有操作或选择。",
          "目标要明确先手、后手和胜负或得分。"
        ],
        "redlines": [
