}

messages.content:
请为当前规则生成一个规划候选。
要求：
- 先判断该规则是否适用，再决定是否继续规划。
- 必须输出完整 new_schema，不要只写自然语言摘要。
- `difference_plan.changed_axes` 必须与 new_schema 的真实变化保持一致。
- 所有参数、输入特性、结构变化和不变量承诺都必须 materialize 到四元组字段里。
- `new_schema` 只能包含约定字段，不要附带任何额外键。
- `algorithmic_delta_claim.new_proof_obligation` 表示新增正确性证明，不要把它写成泛泛的难度评价。
- 必须应用当前规则声明的全部 `helpers`，并把它们完整写入 `applied_helpers`。
- `applied_helpers` 中的每一项都要写清它作用到哪些变化轴、改变了哪些 schema 部分、怎样抬高创新度、怎样抬高难度。
- 如果模式是 same_family_fusion，`shared_core_summary` 和三个 shared_core_anchors 不能为空。
- 如果提供了 `revision_context`，要优先修复其中涉及结构差异、目标定义、规则落地和反换皮风险的问题，并保留 `strengths_to_keep`。
- 若 `revision_context` 包含 `revision_history` 或 `revision_summary`，必须综合此前所有轮次的有用信息，不要只依据最近一轮的修订建议。
- 如果你认为该规则不适用或只能做浅改，请返回失败状态，不要硬套。

{
  "mode": "single_seed_extension",
  "rule": {
    "id": "forward_solution_to_inverse_design",
    "family": "inverse_design",
    "audit_tags": [
      "single_seed",
      "inverse_problem",
      "minimal_edit"
    ],
    "handler": "forward_solution_to_inverse_design",
    "enabled": true,
    "summary": "把正向求解题扩展为给定目标后的最小修改、参数反推或输入设计题。",
    "eligibility": {
      "required_seed_properties": [
        "原题输出或性质可以作为反向目标被指定",
        "存在自然的修改操作或设计自由度"
      ],
      "forbidden_seed_properties": [
        "无法定义可验证的反向目标",
        "修改操作与原核心规律无关"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "forward_solution_to_inverse_design",
      "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
      "new_obligation": "定义目标结果、允许修改和最小性证明"
    },
    "helpers": [
      {
        "id": "target_result_binding",
        "summary": "把原题结果绑定成新题要达成的反向目标。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
        ],
        "redlines": [
          "不能只是问原答案是否等于给定值。",
          "不能让目标与原核心规律脱节。"
        ]
      },
      {
        "id": "edit_operation_contract",
        "summary": "定义允许修改、构造或参数调整的正式操作集合。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把反向设计落实到可枚举或可优化的操作空间。",
        "difficulty_role": "要求证明操作序列与目标结果之间的对应关系。",
        "prompt_guidance": [
          "修改操作必须来自原题对象的自然结构。",
          "不变量要解释修改如何影响目标结果。"
        ],
        "redlines": [
          "不能发明无关操作。",
          "不能让修改只改变叙事外观。"
        ]
      },
      {
        "id": "minimality_or_certificate_lock",
        "summary": "要求输出最小修改代价或可验证设计证据。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承担最小性或构造正确性责任。",
        "difficulty_role": "要求算法证明不能用更少修改达成目标。",
        "prompt_guidance": [
          "输出目标应包含最小代价或具体设计。",
          "不变量要支持下界或正确性证明。"
        ],
        "redlines": [
          "不能只输出任意可行修改。",
          "不能省略最小性证明责任。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "反向目标必须来自原题结果语义",
        "修改操作必须与原核心对象相关",
        "必须承担最小性或设计正确性责任"
      ]
    },
    "examples": {
      "positive": "给定目标答案，求最少修改几个元素使原性质成立。",
      "negative": "随意添加一种与原题无关的操作来构造任意结果。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题无法定义稳定的反向目标或自然修改操作。",
      "difference_insufficient": "反向设计没有改变主求解方向，只是把原判定换了问法。"
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    }
  },
  "theme": {
    "id": "urban_commute",
    "name": "城市通勤",
