            "role_description": "每个测试用例包含整数 N、整数 K，以及 N 行数据，每行包含一个由小写字母组成的字符串 W_i 和 |W_i| 个整数 c_{i,1}...c_{i,|W_i|}，表示将该位置字符替换为任意小写字母的代价。所有字符串总长 ≤ 10^5，代价均为正整数且不超过 10^9。",
            "type": "array",
            "length": {
              "min": 1,
              "max": 100000
            },
            "value_range": {
              "min": null,
              "max": null
            },
            "properties": {}
          }
        ]
      },
      "core_constraints": {
        "constraints": [
          {
            "name": "element_usage_limit",
            "description": "每个原始字符串（经过编辑后）最多在配对中使用一次；若输入中某个字符串出现多次，每个副本独立计数。",
            "formal": "For each i, the (possibly edited) string derived from W_i can be used at most once in the whole verse.",
            "source_sections": [
              "description"
