            "description": "不必使用所有原始字符串（或其编辑后版本），可选择任意子集构成 verse。",
            "formal": "The number of strings used in the verse is ≤ N.",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "alphabet_restriction",
            "description": "所有原始及编辑后的字符串仅由小写英文字母组成。",
            "formal": "Each W_i ∈ [a-z]+, and each edited string ∈ [a-z]+.",
            "source_sections": [
              "constraints"
            ]
          },
          {
            "name": "edit_operation_definition",
            "description": "一次编辑定义为选择一个字符串的某个位置 p，将其字符替换为任意小写字母，并支付该位置对应的代价 c_{i,p}。可对同一字符串的不同位置进行多次编辑，总编辑次数无上限，总代价为各编辑代价之和。",
            "formal": "An edit on string i at position p changes the character to any lowercase letter and incurs cost c_{i,p}. The total edit cost is the sum of costs of all performed edits.",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "target_beauty_threshold",
            "description": "必须存在一个编辑方案和一个合法配对方案，使得总 beauty 至少为 K。若不存在，输出 -1。",
            "formal": "∃ edit plan and selection of stanzas such that ∑ min(l_p, l_s)^2 ≥ K. If impossible, output -1.",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "beauty_definition",
            "description": "两个字符串的 beauty 定义为 min(最长公共前缀长度, 最长公共后缀长度) 的平方。",
            "formal": "beauty(a,b) = min(|lcp(a,b)|, |lcs(a,b)|)^2",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "cost_range",
            "description": "所有代价 c_{i,p} 均为正整数，且不超过 10^9。",
            "formal": "1 ≤ c_{i,p} ≤ 10^9",
            "source_sections": [
              "constraints"
            ]
          }
        ]
      },
      "objective": {
        "type": "minimize_cost",
        "description": "最小化总编辑代价，使得编辑后的字符串集合存在一种合法配对（verse），其总 beauty 至少为 K。若无法达到 K，输出 -1。",
        "target": "total_edit_cost",
        "requires_solution": false
      },
      "invariant": {
        "invariants": [
          {
            "name": "transformed_lcp_correspondence",
            "description": "将每个字符串与其反转交错合并形成新字符串后，任意两个字符串的原始 beauty 值 min(lp,ls)^2 等于新字符串间最长公共前缀长度一半的平方，从而可通过交错字符串的 LCP 计算 beauty。",
            "properties": {
              "formula": "for any strings w1,w2, let t1=interleave(w1,reverse(w1)), t2=interleave(w2,reverse(w2)). Then min(lcp(w1,w2), lcs(w1,w2)) = lcp(t1,t2) // 2"
            },
            "evidence_source": "both"
          },
          {
            "name": "edit_monotonicity_with_cost",
            "description": "对于任一字符串的任意单次编辑，其引起的总 beauty 增量 Δ 受到编辑代价 c 的约束，即 Δ ≤ h(c)，其中 h 是预定义的单调非减函数。此函数基于字符改变对 LCP 的局部影响上限推导得出，保证代价与 beauty 增益之间的定量关系。",
            "properties": {
              "condition": "For any single edit with cost c, the increase in total beauty of the optimal verse is at most h(c), where h is a non-decreasing function derived from the LCP structure."
