messages.content:
请审查该题面是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用题面、`new_schema`、规划摘要或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要确认题面把这些 helper 的语义承诺写清，而不是只在规划摘要里出现。
- 如果题面没有把关键语义写清楚，返回 `fail`。

{
  "review_type": "rule_problem_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名反向设计题面审查官，重点确认题面是否写清目标、修改操作和最小性语义。",
  "review_brief": "确认题面是否要求用最少修改或具体设计达成目标，并且修改操作来自原题对象。",
  "rule_under_review": {
    "id": "forward_solution_to_inverse_design",
    "family": "inverse_design",
    "summary": "把正向求解题扩展为给定目标后的最小修改、参数反推或输入设计题。",
    "audit_tags": [
      "single_seed",
      "inverse_problem",
      "minimal_edit"
    ],
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "forward_solution_to_inverse_design",
      "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
      "new_obligation": "定义目标结果、允许修改和最小性证明"
    },
    "helpers": [
      {
        "id": "target_result_binding",
        "summary": "把原题结果绑定成新题要达成的反向目标。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
        ],
        "redlines": [
          "不能只是问原答案是否等于给定值。",
          "不能让目标与原核心规律脱节。"
        ]
      },
      {
        "id": "edit_operation_contract",
        "summary": "定义允许修改、构造或参数调整的正式操作集合。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把反向设计落实到可枚举或可优化的操作空间。",
        "difficulty_role": "要求证明操作序列与目标结果之间的对应关系。",
        "prompt_guidance": [
          "修改操作必须来自原题对象的自然结构。",
          "不变量要解释修改如何影响目标结果。"
        ],
        "redlines": [
          "不能发明无关操作。",
          "不能让修改只改变叙事外观。"
        ]
      },
      {
        "id": "minimality_or_certificate_lock",
        "summary": "要求输出最小修改代价或可验证设计证据。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承担最小性或构造正确性责任。",
        "difficulty_role": "要求算法证明不能用更少修改达成目标。",
        "prompt_guidance": [
          "输出目标应包含最小代价或具体设计。",
          "不变量要支持下界或正确性证明。"
        ],
        "redlines": [
          "不能只输出任意可行修改。",
          "不能省略最小性证明责任。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "反向目标必须来自原题结果语义",
        "修改操作必须与原核心对象相关",
        "必须承担最小性或设计正确性责任"
      ]
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    },
    "examples": {
      "positive": "给定目标答案，求最少修改几个元素使原性质成立。",
      "negative": "随意添加一种与原题无关的操作来构造任意结果。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题无法定义稳定的反向目标或自然修改操作。",
      "difference_insufficient": "反向设计没有改变主求解方向，只是把原判定换了问法。"
    }
  },
  "plan_context": {
    "mode": "single_seed_extension",
    "applied_rule": "forward_solution_to_inverse_design",
    "objective": {
      "type": "minimize_cost",
      "description": "最小化总编辑代价，使得编辑后的字符串集合存在一种合法配对（verse），其总 beauty 至少为 K。若无法达到 K，输出 -1。",
      "target": "total_edit_cost",
      "requires_solution": false
    },
    "difference_plan": {
      "target_distance_band": {
        "min": 0.35,
        "max": 0.6
      },
      "changed_axes": [
        "C",
        "O",
        "V"
      ],
      "same_family_allowed": true,
      "forbidden_reuse": [
        "taco_codechef_4a283930e669",
        "ENGLISH",
        "codechef",
        "Read problem statements in [Hindi], [Bengali], [Mandarin Chinese], [Russian], and [Vietnamese] as well. Chef is learning English. So far, he knows $N$ words, and he wants to write a verse. Let's call a pair of English...",
        "不要复写原题的叙事结构、任务定义或样例套路。",
        "不要只替换实体名称后保留同样的输入输出关系。"
      ],
      "rationale": "核心约束新增带代价的编辑操作与目标 beauty 阈值；目标从最大化翻转为最小化代价；不变量从单纯 LCP 分治转为代价感知的 beauty 提升界限与最小性证明。输入结构增加编辑代价和阈值参数，但整体结构仍为多测试用例与字符串序列，因此 I 轴未发生根本改变。",
      "summary": "从计算最大 beauty 的优化问题转为在给定编辑代价矩阵下求最小总代价使 beauty ≥ K 的逆设计问题，核心约束、目标与不变量发生实质扭转。",
      "mode": "single_seed_extension"
    },
    "algorithmic_delta_claim": {
      "seed_solver_core": "将每个单词与其反转交错生成新字符串，按字典序排序，利用相邻最小 LCP 分割进行分治递归，最大化配对 beauty 总和。",
      "reusable_subroutines": "字符串交错变换、字符串反转、字符串排序、相邻 LCP 计算、分治递归框架（左右子问题合并时计算未配对单词间的 beauty）。",
      "new_solver_core": "在排序后交错序列的基础上，需要设计状态搜索或动态规划，为每个字符串选择编辑位置和编辑结果，使得总代价最小且总 beauty ≥ K。可能的方法包括：预处理每个字符串在不编辑和各位置编辑下的潜在 LCP 提升量，建立二分图或最小代价流模型，在约束下选择编辑决策并保证配对的最大 beauty 达到阈值。需开发全新的代价感知优化算法。",
      "new_proof_obligation": "必须证明编辑操作对总 beauty 提升的上界关于其代价的函数关系 h(c)，并利用此关系推导最小编辑代价下界，证明算法所得代价为最小。同时需证明在代价非均匀时，任何总代价更小的方案均无法达到 K，且算法在考虑多字符串协同编辑时保持了最优性。另外，需证明在搜索空间极大的情况下，编辑后的字符串仍能有效维持排序窗口引理，保证算法复杂度可接受。",
      "why_direct_reuse_fails": "原算法直接最大化 beauty，完全未涉及编辑操作与代价，也无法回答“为达到指定 beauty 最少需要多少代价”。直接调用原解法只能获取未编辑时的最大 beauty，但无法指导如何分配编辑预算，也无法保证编辑后的字符串序列仍能套用原递归框架的最优性，因为编辑可能改变字符串间的 LCP 关系及排序。"
    },
    "shared_core_summary": "",
    "shared_core_anchors": {
      "shared_state": "",
      "shared_transition": "",
      "shared_decision_basis": ""
    },
    "seed_contributions": {
      "seed_a": "",
      "seed_b": ""
    },
    "fusion_ablation": {
      "without_seed_a": "",
      "without_seed_b": ""
    },
    "applied_helpers": [
      {
        "id": "target_result_binding",
        "selection_reason": "原题输出 beauty 值，可绑定为新题的达成目标 K，驱动反向设计。",
        "affected_axes": [
          "C",
          "O"
        ],
        "schema_changes": [
          "core_constraints 增加 target_beauty_threshold，要求总 beauty ≥ K",
