    try:
        lines = input_string.strip().split('\n')
        if not lines:
            return False
        T = int(lines[0])
        if not (1 <= T <= 10**5):
            return False
        idx = 1
        total_N = 0
        total_len = 0
        for _ in range(T):
            if idx >= len(lines):
                return False
            parts = lines[idx].split()
            if len(parts) != 2:
                return False
            N = int(parts[0])
            K = int(parts[1])
            if not (1 <= N <= 10**5 and 0 <= K <= 10**18):
                return False
            total_N += N
            if total_N > 10**5:
                return False
            idx += 1
            for _ in range(N):
                if idx >= len(lines):
                    return False
                line_parts = lines[idx].split()
                if not line_parts:
                    return False
                Wi = line_parts[0]
                if not Wi.islower() or Wi == "":
                    return False
                length = len(Wi)
                total_len += length
                if total_len > 10**5:
                    return False
                if len(line_parts) != 1 + length:
                    return False
                for c in line_parts[1:]:
                    cost = int(c)
                    if not (1 <= cost <= 10**9):
                        return False
                idx += 1
        if idx != len(lines):
            return False  # 多余行
        if total_N > 10**5 or total_len > 10**5:
            return False
        return True
    except Exception:
        return False

def validate_test_input(input_string):
