import sys
from itertools import product

def min_cost_pair(s1, s2, cost1, cost2):
    n1, n2 = len(s1), len(s2)
    maxL = min(n1, n2)
    costs = [0] * (maxL + 1)
    for L in range(1, maxL + 1):
        total_nodes = n1 + n2
        parent = list(range(total_nodes))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[ry] = rx

        # 前缀约束
        for j in range(L):
            union(j, n1 + j)
        # 后缀约束
        for t in range(L):
            u = n1 - 1 - t
            v = n1 + n2 - 1 - t
            union(u, v)

        # 收集各分量的节点信息
        comp = {}
        for u in range(total_nodes):
            root = find(u)
            if root not in comp:
                comp[root] = {}
            if u < n1:
                ch = s1[u]
                c = cost1[u]
            else:
                ch = s2[u - n1]
                c = cost2[u - n1]
            comp[root][u] = (ch, c)

        total_cost = 0
        for nodes_in_comp in comp.values():
            nodes_info = list(nodes_in_comp.values())
            min_comp_cost = float('inf')
            for target_ord in range(26):
                target = chr(ord('a') + target_ord)
                cur = 0
                for ch, c in nodes_info:
                    if ch != target:
                        cur += c
                if cur < min_comp_cost:
                    min_comp_cost = cur
            total_cost += min_comp_cost
        costs[L] = total_cost
    return costs

def solve(input_str: str) -> str:
    data = input_str.split()
    if not data:
        return ''
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        strings = []
        costs = []
        for i in range(N):
            s = next(it)
            strings.append(s)
            c_list = [int(next(it)) for __ in range(len(s))]
            costs.append(c_list)
        if K == 0:
            out_lines.append('0')
            continue
        if N < 2:
            out_lines.append('-1')
            continue

        # 生成所有配对划分
        def gen_pairings(indices):
            if len(indices) <= 1:
                return [[]]
            res = []
            # 跳过 indices[0]
            for sub in gen_pairings(indices[1:]):
                res.append(sub)
            # 将 indices[0] 与某个其它索引配对
            for j in range(1, len(indices)):
                pair = (indices[0], indices[j])
                remaining = indices[1:j] + indices[j+1:]
                for sub in gen_pairings(remaining):
                    res.append([pair] + sub)
            return res

        indices = list(range(N))
        pairings = gen_pairings(indices)

        # 预处理所有对(i,j)的costs
        precomputed = {}
        for i in range(N):
            for j in range(i+1, N):
                precomputed[(i,j)] = min_cost_pair(strings[i], strings[j],
                                                   costs[i], costs[j])

        min_total_cost = float('inf')
        for pairing in pairings:
            m = len(pairing)
            if m == 0:
                continue
            pairs_info = []
            for (i,j) in pairing:
                pair_costs = precomputed[(i,j)]
                maxL = len(pair_costs) - 1
                pairs_info.append((maxL, pair_costs))

            L_ranges = [range(p[0]+1) for p in pairs_info]
            for L_tuple in product(*L_ranges):
                total_beauty = sum(L*L for L in L_tuple)
                if total_beauty >= K:
                    total_cost = sum(pairs_info[idx][1][L]
                                     for idx, L in enumerate(L_tuple))
                    if total_cost < min_total_cost:
                        min_total_cost = total_cost

        if min_total_cost == float('inf'):
            out_lines.append('-1')
        else:
            out_lines.append(str(min_total_cost))
    return '\n'.join(out_lines)

