import sys, math

def solve(input_str: str) -> str:
    data = input_str.strip().split()
    if not data:
        return ''
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        strings = []
        costs = []
        for i in range(N):
            Wi = next(it)
            ci = []
            for _ in range(len(Wi)):
                ci.append(int(next(it)))
            strings.append(Wi)
            costs.append(ci)
        if K == 0:
            out_lines.append('0')
            continue
        L = math.isqrt(K)
        if L * L < K:
            L += 1
        min_total = float('inf')
        for i in range(N):
            for j in range(i+1, N):
                s, cs = strings[i], costs[i]
                t, ct = strings[j], costs[j]
                n, m = len(s), len(t)
                if n < L or m < L:
                    continue
                cost = 0
                for p in range(L):
                    if s[p] != t[p]:
                        cost += min(cs[p], ct[p])
                for p in range(L):
                    idx_s = n - L + p
                    idx_t = m - L + p
                    if s[idx_s] != t[idx_t]:
                        cost += min(cs[idx_s], ct[idx_t])
                if cost < min_total:
                    min_total = cost
        if min_total == float('inf'):
            out_lines.append('-1')
        else:
            out_lines.append(str(min_total))
    return '\n'.join(out_lines)

