{"code": "import sys
from math import ceil

def beauty_wo_square(s1, s2):  # 计算匹配度，但忘记平方
    min_len = min(len(s1), len(s2))
    lcp = 0
    for i in range(min_len):
        if s1[i] == s2[i]:
            lcp += 1
        else:
            break
    lcs = 0
    for i in range(1, min_len + 1):
        if s1[-i] == s2[-i]:
            lcs += 1
        else:
            break
    return min(lcp, lcs)

def solve(input_str: str) -> str:
    data = input_str.split()
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        strings = []
        costs = []
        for i in range(N):
            s = next(it)
            strings.append(s)
            cost_row = []
            for _ in range(len(s)):
                cost_row.append(int(next(it)))
            costs.append(cost_row)
        # K=0 无需编辑
        if K == 0:
            out_lines.append("0")
            continue

        # 按长度分组
        len_groups = {}
        for i, s in enumerate(strings):
            L = len(s)
