import sys
from math import ceil

def beauty_wo_square(s1, s2):  # 计算匹配度，但忘记平方
    min_len = min(len(s1), len(s2))
    lcp = 0
    for i in range(min_len):
        if s1[i] == s2[i]:
            lcp += 1
        else:
            break
    lcs = 0
    for i in range(1, min_len + 1):
        if s1[-i] == s2[-i]:
            lcs += 1
        else:
            break
    return min(lcp, lcs)

def solve(input_str: str) -> str:
    data = input_str.split()
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
