        K = int(next(it))
        strings = []
        costs = []
        for i in range(N):
            s = next(it)
            strings.append(s)
            cost_row = []
            for _ in range(len(s)):
                cost_row.append(int(next(it)))
            costs.append(cost_row)
        # K=0 无需编辑
        if K == 0:
            out_lines.append("0")
            continue

        # 按长度分组
        len_groups = {}
        for i, s in enumerate(strings):
            L = len(s)
            if L not in len_groups:
                len_groups[L] = []
            len_groups[L].append((s, costs[i]))

