{"code": "import sys
import math

def solve(input_str: str) -> str:
    data = input_str.split()
    it = iter(data)
    T = int(next(it))
    outputs = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        strings = []
        costs = []
        for _ in range(N):
            w = next(it)
            L = len(w)
            c = [int(next(it)) for _ in range(L)]
            strings.append(w)
            costs.append(c)

        if K == 0:
            outputs.append('0')
            continue

        s = math.ceil(math.sqrt(K))  # 需要的最短前后缀长度

        # 错误策略：允许同一条线路自身配对
        # 检查是否存在一条线路自身配对即可满足 K
        can_self_pair = False
        for i in range(N):
            if len(strings[i]) >= s:
                # 自身配对时匹配度为长度平方，无需任何编辑
                can_self_pair = True
                break
        if can_self_pair:
            outputs.append('0')
            continue

        # 若不存在自配对满足条件，尝试两两配对
        min_cost = float('inf')
        for i in range(N):
            len_i = len(strings[i])
            if len_i < s:
                continue
            for j in range(i + 1, N):
                len_j = len(strings[j])
                if len_j < s:
                    continue
                # 简单认为前后缀不重叠，要求长度至少 2*s（错误简化）
                if len_i < 2 * s or len_j < 2 * s:
                    continue
                # 计算前缀代价
                pre_cost = 0
                for p in range(s):
                    if strings[i][p] == strings[j][p]:
                        continue
                    pre_cost += min(costs[i][p], costs[j][p])
                # 计算后缀代价
                suf_cost = 0
                for p in range(s):
                    pi = len_i - 1 - p
                    pj = len_j - 1 - p
                    if strings[i][pi] == strings[j][pj]:
                        continue
                    suf_cost += min(costs[i][pi], costs[j][pj])
                total = pre_cost + suf_cost
                if total < min_cost:
                    min_cost = total

        if min_cost == float('inf'):
            outputs.append('-1')
        else:
            outputs.append(str(min_cost))

    return '\n'.join(outputs)
"}

