题目约束：T组测试用例，所有用例N之和≤1e5，所有线路长度之和≤1e5。每条线路Wi长度|Wi|∈[1,1e5]，cij∈[1,1e9]，K∈[0,1e18]。对抗策略包括：(1)边界规模：T=1且N=1e5,长度=1，总N和总长度触及上限；或T=1e5且每个N=1,长度=1，同样触及总和上限，测试大量用例情况；(2)极端K：K=0或K=1e18，测试边界答案；(3)退化字符串：所有字符串完全相同且长度较大，匹配度易计算，但需选择最优配对；(4)多样字符串与高代价：随机串，无公共前后缀，迫使大量编辑；(5)混合策略：随机分配N和长度，K随机。生成时严格保持总N与总长度不超过1e5。

# 当前 generate_test_input_code

import cyaron as cy
import random

def generate_test_input():
    strategy = random.choice([
        'max_total_n',
        'max_total_cases',
        'extreme_k_zero',
        'extreme_k_large',
        'identical_strings',
        'diverse_high_cost',
        'random_mix'
    ])

    if strategy == 'max_total_n':
        T = 1
        N = 100000
        K = random.choice([0, 10**18, cy.randint(0, 10**18)])
        lines = []
        for _ in range(N):
            Wi = cy.String.random(1, charset="abcdefghijklmnopqrstuvwxyz")
            cost = cy.randint(1, 10**9)
            lines.append(f"{Wi} {cost}")
        return f"{T}\n{N} {K}\n" + "\n".join(lines)

    elif strategy == 'max_total_cases':
        T = 100000
        cases_lines = []
        for _ in range(T):
            N = 1
            Wi = cy.String.random(1, charset="abcdefghijklmnopqrstuvwxyz")
            cost = cy.randint(1, 10**9)
            K = random.choice([0, 10**18, cy.randint(0, 10**18)])
            cases_lines.append(f"{N} {K}")
            cases_lines.append(f"{Wi} {cost}")
        return f"{T}\n" + "\n".join(cases_lines)

    elif strategy == 'extreme_k_zero':
        T = cy.randint(1, 10)
        K = 0
        total_N = 0
        total_len = 0
        case_data = []
        for _ in range(T):
            max_N = min(100000 - total_N, 10000)
            if max_N <= 0:
                break
            N = cy.randint(1, max_N)
            total_N += N
            if total_N > 100000:
                N -= (total_N - 100000)
                total_N = 100000
            strings = []
            for _ in range(N):
                rem_len = 100000 - total_len
                if rem_len <= 0:
                    break
                max_len = min(rem_len, 10000)
                length = cy.randint(1, max_len)
                Wi = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
                costs = [cy.randint(1, 10**9) for _ in range(length)]
                strings.append((Wi, costs))
                total_len += length
            case_data.append((N, K, strings))
            if total_N >= 100000 or total_len >= 100000:
                break
        lines = [str(len(case_data))]
        for N, K, strings in case_data:
            lines.append(f"{N} {K}")
            for Wi, costs in strings:
                lines.append(Wi + " " + " ".join(map(str, costs)))
        return "\n".join(lines)

    elif strategy == 'extreme_k_large':
        K = 10**18
        T = cy.randint(1, 10)
        total_N = 0
        total_len = 0
        case_data = []
        for _ in range(T):
            max_N = min(100000 - total_N, 10000)
            if max_N <= 0:
                break
            N = cy.randint(1, max_N)
            total_N += N
            strings = []
            for _ in range(N):
                rem_len = 100000 - total_len
                if rem_len <= 0:
                    break
                max_len = min(rem_len, 10000)
                length = cy.randint(1, max_len)
                Wi = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
                costs = [random.randint(1, 10**9) for _ in range(length)]
                strings.append((Wi, costs))
                total_len += length
            case_data.append((N, K, strings))
            if total_N >= 100000 or total_len >= 100000:
                break
        lines = [str(len(case_data))]
        for N, K, strings in case_data:
            lines.append(f"{N} {K}")
            for Wi, costs in strings:
                lines.append(Wi + " " + " ".join(map(str, costs)))
        return "\n".join(lines)

    elif strategy == 'identical_strings':
        T = 1
        N = cy.randint(2, 1000)
        length = 100000 // N
        if length < 1:
            length = 1
        base = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
        costs = [cy.randint(1, 10**9) for _ in range(length)]
        K = random.choice([0, (length*length) * (N//2)])
        lines = [f"{T}", f"{N} {K}"]
        for _ in range(N):
            lines.append(base + " " + " ".join(map(str, costs)))
        return "\n".join(lines)

    elif strategy == 'diverse_high_cost':
        T = 1
        N = cy.randint(2, 1000)
        length = 100000 // N
        if length < 1:
            length = 1
        K = 10**18
        lines = [f"{T}", f"{N} {K}"]
        for _ in range(N):
            Wi = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
            costs = [cy.randint(1, 10**9) for _ in range(length)]
            lines.append(Wi + " " + " ".join(map(str, costs)))
        return "\n".join(lines)

    else:  # random_mix
        T = cy.randint(1, 10)
        total_N = 0
        total_len = 0
        case_data = []
        for _ in range(T):
            max_N = min(100000 - total_N, 10000)
            if max_N <= 0:
                break
            N = cy.randint(1, max_N)
            total_N += N
            strings = []
            for _ in range(N):
                rem_len = 100000 - total_len
                if rem_len <= 0:
                    break
                max_len = min(rem_len, 10000)
                length = cy.randint(1, max_len)
                Wi = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
                costs = [cy.randint(1, 10**9) for _ in range(length)]
                strings.append((Wi, costs))
                total_len += length
            K = random.choice([0, cy.randint(0, 10**18)])
            case_data.append((N, K, strings))
            if total_N >= 100000 or total_len >= 100000:
                break
        lines = [str(len(case_data))]
        for N, K, strings in case_data:
            lines.append(f"{N} {K}")
            for Wi, costs in strings:
                lines.append(Wi + " " + " ".join(map(str, costs)))
        return "\n".join(lines)


# 当前 validate_test_input_code

def validate_test_input(input_string):
    try:
        lines = input_string.strip().split('\n')
        if not lines:
            return False
        T = int(lines[0])
        if not (1 <= T <= 100000):
            return False
        idx = 1
        total_N = 0
        total_len = 0
        for _ in range(T):
            if idx >= len(lines):
                return False
            parts = lines[idx].split()
            if len(parts) < 2:
                return False
            N = int(parts[0])
            K = int(parts[1])
            if not (1 <= N <= 100000):
                return False
            if not (0 <= K <= 10**18):
                return False
            idx += 1
            for _ in range(N):
                if idx >= len(lines):
                    return False
                parts = lines[idx].split()
                if not parts:
                    return False
                Wi = parts[0]
                if not (isinstance(Wi, str) and 1 <= len(Wi) <= 100000 and Wi.isalpha() and Wi.islower()):
                    return False
                costs = parts[1:]
                if len(costs) != len(Wi):
                    return False
                try:
                    costs = [int(c) for c in costs]
                except ValueError:
                    return False
                if not all(1 <= c <= 10**9 for c in costs):
                    return False
                total_N += 1
                total_len += len(Wi)
                if total_N > 100000 or total_len > 100000:
                    return False
                idx += 1
        if idx != len(lines):
            return False
        return total_N <= 100000 and total_len <= 100000
    except Exception:
        return False


