        'extreme_k_large',
        'identical_strings',
        'diverse_high_cost',
        'random_mix'
    ])

    if strategy == 'max_total_n':
        T = 1
        N = 100000
        K = random.choice([0, 10**18, cy.randint(0, 10**18)])
        lines = []
        for _ in range(N):
            Wi = cy.String.random(1, charset="abcdefghijklmnopqrstuvwxyz")
            cost = cy.randint(1, 10**9)
            lines.append(f"{Wi} {cost}")
        return f"{T}\n{N} {K}\n" + "\n".join(lines)

    elif strategy == 'max_total_cases':
        T = 100000
        cases_lines = []
        for _ in range(T):
            N = 1
            Wi = cy.String.random(1, charset="abcdefghijklmnopqrstuvwxyz")
            cost = cy.randint(1, 10**9)
            K = random.choice([0, 10**18, cy.randint(0, 10**18)])
            cases_lines.append(f"{N} {K}")
            cases_lines.append(f"{Wi} {cost}")
        return f"{T}\n" + "\n".join(cases_lines)

    elif strategy == 'extreme_k_zero':
        T = cy.randint(1, 10)
        K = 0
        total_N = 0
        total_len = 0
        case_data = []
        for _ in range(T):
            max_N = min(100000 - total_N, 10000)
            if max_N <= 0:
                break
            N = cy.randint(1, max_N)
            total_N += N
            if total_N > 100000:
                N -= (total_N - 100000)
                total_N = 100000
            strings = []
            for _ in range(N):
                rem_len = 100000 - total_len
                if rem_len <= 0:
                    break
                max_len = min(rem_len, 10000)
                length = cy.randint(1, max_len)
                Wi = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
                costs = [cy.randint(1, 10**9) for _ in range(length)]
                strings.append((Wi, costs))
                total_len += length
            case_data.append((N, K, strings))
            if total_N >= 100000 or total_len >= 100000:
                break
        lines = [str(len(case_data))]
        for N, K, strings in case_data:
