            for Wi, costs in strings:
                lines.append(Wi + " " + " ".join(map(str, costs)))
        return "\n".join(lines)

    elif strategy == 'identical_strings':
        T = 1
        N = cy.randint(2, 1000)
        length = 100000 // N
        if length < 1:
            length = 1
        base = cy.String.random(length, charset="abcdefghijklmnopqrstuvwxyz")
