def validate_test_input(input_string):
    try:
        lines = input_string.strip().split('\n')
        if not lines:
            return False
        T = int(lines[0])
        if not (1 <= T <= 100000):
            return False
        idx = 1
        total_N = 0
        total_len = 0
        for _ in range(T):
            if idx >= len(lines):
                return False
            parts = lines[idx].split()
            if len(parts) < 2:
                return False
            N = int(parts[0])
            K = int(parts[1])
            if not (1 <= N <= 100000):
                return False
            if not (0 <= K <= 10**18):
                return False
            idx += 1
            for _ in range(N):
                if idx >= len(lines):
                    return False
                parts = lines[idx].split()
                if not parts:
                    return False
                Wi = parts[0]
                if not (isinstance(Wi, str) and 1 <= len(Wi) <= 100000 and Wi.isalpha() and Wi.islower()):
                    return False
                costs = parts[1:]
                if len(costs) != len(Wi):
                    return False
                try:
                    costs = [int(c) for c in costs]
                except ValueError:
                    return False
                if not all(1 <= c <= 10**9 for c in costs):
                    return False
                total_N += 1
                total_len += len(Wi)
                if total_N > 100000 or total_len > 100000:
                    return False
                idx += 1
        if idx != len(lines):
            return False
        return total_N <= 100000 and total_len <= 100000
    except Exception:
        return False


