{
  "status": "ok",
  "error_reason": "",
  "feedback": "",
  "eligibility_reason": "原题输出（最小半径）可作为反向目标被指定为固定半径 R；存在自然的修改操作（移动寺庙）；最小修改代价可定义。",
  "core_transformation_summary": "将原题求解最小 enlightenment 值转换为给定 enlightenment 值 R，求最少移动寺庙位置使其可被 K 个僧侣覆盖。",
  "difference_plan": {
    "changed_axes": ["I", "C", "O", "V"],
    "rationale": "输入增加固定半径 R（I）；核心约束新增固定 enlightenment 与移动操作（C）；目标从最小半径转为最小移动次数（O）；不变量新增移动等价性与最优子结构支撑最小性证明（V）。",
    "summary": "原题：给定点集，求最小半径 R 使 K 个僧侣覆盖所有点。新题：给定半径 R，允许移动点，求最少移动次数使 K 个僧侣仍能覆盖。"
  },
  "new_schema": {
    "problem_id": "proj_inv_design_temples_move",
    "source": "derived",
    "input_structure": {
      "type": "composite",
      "length": { "min": null, "max": null },
      "value_range": { "min": null, "max": null },
      "properties": {},
      "components": [
        {
          "role": "parameters",
          "role_description": "three integers: number of temples N, number of monks K, target enlightenment value R",
          "type": "tuple",
          "length": { "min": 3, "max": 3 },
          "value_range": { "min": null, "max": null },
          "properties": { "ordered": true }
        },
        {
          "role": "positions",
          "role_description": "integer positions of the N temples on the line",
          "type": "array",
          "length": { "min": null, "max": null },
          "value_range": { "min": 1, "max": 10000000 },
          "properties": {}
        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "fixed_enlightenment",
          "description": "All monks have an enlightenment value (range) equal to the given integer R. This value is fixed and cannot be changed.",
          "formal": "r_j = R for all j=1..K, R given as input",
          "source_sections": ["description"]
        },
        {
          "name": "num_monks",
          "description": "Exactly K monks are available to be placed. Each monk can be placed at any real coordinate on the line.",
          "formal": "|monks| = K, c_j ∈ ℝ",
          "source_sections": ["description"]
        },
        {
          "name": "move_operation",
          "description": "You may choose to change the position of any temple. Moving a temple from its original position p_i to a new integer position p_i' costs 1. Moved temples must remain within the valid range [1, 10^7].",
          "formal": "For each i, choose p_i' ∈ ℤ, 1 ≤ p_i' ≤ 1e7; cost = count(p_i' ≠ p_i)",
          "source_sections": ["description"]
        },
        {
          "name": "complete_coverage_after_moves",
          "description": "After all chosen moves, the set of final temple positions must be completely covered by the K monks' enlightenment ranges of radius R. That is, for every temple i, there exists a monk j such that |p_i' - c_j| ≤ R.",
          "formal": "∀i ∃j: |p_i' - c_j| ≤ R",
          "source_sections": ["description"]
        },
        {
          "name": "monks_less_than_temples",
          "description": "Number of monks is strictly less than number of temples (K < N) to avoid trivial zero‑move cases.",
          "formal": "K < N",
          "source_sections": ["constraints"]
        }
      ]
    },
    "objective": {
      "type": "minimize_value",
      "description": "最小化移动寺庙的次数（即改变位置的寺庙个数），使得移动后所有寺庙可以被给定的 enlightenment 值 R 和 K 个僧侣完全覆盖。",
      "target": "moves"
    },
    "invariant": {
      "invariants": [
        {
          "name": "feasibility_preservation",
          "description": "If a set of temple positions can be covered by K monks with radius R, then any superset of positions that is contained within the same coverage regions can also be covered. This ensures that moving a temple into an already covered area does not break coverage.",
          "properties": {},
          "evidence_source": "deduction"
        },
        {
          "name": "greedy_min_monks",
          "description": "For any set of points S, the minimum number of monks needed to cover them with radius R is given by a greedy algorithm that scans left-to-right and places a monk at (first uncovered point + R). This is a standard result and provides a feasibility test.",
          "properties": {},
          "evidence_source": "known"
        },
        {
          "name": "move_equivalence",
          "description": "Minimizing moves is equivalent to maximizing the size of a subset S of the original points that can be covered by ≤ K monks with radius R, because any point not in S can be moved into a coverage region (e.g., to the center of an existing monk) at cost 1 each.",
          "properties": {},
          "evidence_source": "deduction"
        },
        {
          "name": "optimal_substructure",
          "description": "On the sorted points, an optimal retained subset S can be partitioned into at most K contiguous segments such that within each segment the span (max - min) ≤ 2R. This allows DP on intervals.",
          "properties": {},
          "evidence_source": "deduction"
        }
      ]
    },
    "difficulty": "medium-hard"
