    }
  ],
  "skipped": [
    {
      "source_case_id": "case_001",
      "strategy": "OBJECTIVE_NON_OPTIMAL_TOO_LARGE",
      "reason": "该题或该输出无法确认是最小化问题，因此跳过"
    }
  ]
