def check_output(input_string, output_string):
    try:
        # 解析输入
        lines_in = input_string.strip().split('\n')
        if not lines_in:
            return False
        first_line = lines_in[0].strip().split()
        if len(first_line) != 3:
            return False
        N, K, R = map(int, first_line)
        if not (1 <= N <= 100000 and 1 <= K < N and 1 <= R <= 10000000):
            return False
        if len(lines_in) < 2:
            return False
        pos_line = lines_in[1].strip().split()
        if len(pos_line) != N:
            return False
        initial = [int(x) for x in pos_line]
        # 解析输出
        lines_out = output_string.strip().split('\n')
        # 去除可能存在的空行
        lines_out = [line.strip() for line in lines_out if line.strip() != '']
        if len(lines_out) != N + 1:
            return False
        try:
            M = int(lines_out[0])
        except Exception:
            return False
        if not (0 <= M <= N):
            return False
        final = []
        for i in range(1, N + 1):
            try:
                val = int(lines_out[i])
            except Exception:
                return False
            final.append(val)
        # 验证移动次数
        moves = sum(1 for i in range(N) if initial[i] != final[i])
        if moves != M:
            return False
        # 验证覆盖可行性（贪心）
        sorted_final = sorted(final)
        need = 0
        i = 0
        while i < N:
            center = sorted_final[i] + R
            need += 1
            if need > K:  # 提前结束
                return False
            # 跳过所有覆盖在该僧侣范围内的点
            while i < N and sorted_final[i] <= center + R:
                i += 1
        return need <= K
    except Exception:
        return False

